/// <summary>
/// PricingAttribute of table <c>InventTable</c> field CostBOMLevel.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Product, UPSPricingAttributeSourceLevel::Line)]
internal class UPSPricingAttributeInventTableCostBOMLevel extends UPSPricingAttributeInventTable implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(InventTable, CostBOMLevel);
}

public Set getAllowedValues()
{
    var ret = new Set(Types::Integer);
    InventTable inventTable;
    while select CostBOMLevel from inventTable
        group by CostBOMLevel
    {
        ret.add(inventTable.CostBOMLevel);
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(InventTable, CostBOMLevel));
    qbr.value(queryValue(_value));
}
